from __future__ import annotations

try:  # pragma: no cover - package import path
    import troTHU.runtime_context as ctx
except ImportError:  # pragma: no cover - direct script fallback
    import runtime_context as ctx  # type: ignore


def __getattr__(name: str):
    return getattr(ctx, name)


def _add_teacher_page_args(parser: ctx.Any, *, conditions: bool = True) -> None:
    parser.add_argument('--page', type=int, default=1, help='page number')
    parser.add_argument('--page-size', type=int, default=20, help='page size')
    if conditions:
        parser.add_argument('--conditions', default='', help='optional JSON conditions string')


def _add_teacher_json_flags(
    parser: ctx.Any,
    *,
    max_courses: bool = False,
    sensitive: bool = True,
) -> None:
    parser.add_argument('--json', action='store_true', help='print JSON')
    if max_courses:
        parser.add_argument('--max-courses', type=int, default=50, help='maximum courses to inspect for role detection')
    if sensitive:
        parser.add_argument('--include-sensitive', action='store_true', help='include sensitive fields in the response summary')


def _add_teacher_action_flags(parser: ctx.Any, *, payload: bool = False, payload_required: bool = False) -> None:
    if payload:
        kwargs = {'help': 'JSON object payload to send'}
        if payload_required:
            kwargs['required'] = True
        else:
            kwargs['default'] = ''
        parser.add_argument('--payload-json', **kwargs)
    parser.add_argument('--execute', action='store_true', help='actually send the request; default is dry-run preview')
    parser.add_argument('--yes', action='store_true', help='confirm the teacher-side change when used with --execute')
    parser.add_argument('--json', action='store_true', help='print JSON')
    parser.add_argument('--include-sensitive', action='store_true', help='include sensitive fields in the request/response summary')


def _add_teacher_download_flags(parser: ctx.Any) -> None:
    parser.add_argument('--output', required=True, help='output file path, or an existing directory')
    parser.add_argument('--overwrite', action='store_true', help='overwrite the output file if it already exists')
    parser.add_argument('--json', action='store_true', help='print JSON')


